from pathlib import Path
p=Path('campaign-client.js');s=p.read_text(encoding='utf-8-sig')
s=s.replace("const left=el('section','campaign-candidates')", "const strategy=el('select','campaign-strategy');strategy.setAttribute('aria-label','Estratégia da equipe');for(const [value,label] of [['aggressive','Agressiva — explorar a vulnerabilidade'],['cautious','Cautelosa — desviar dos ataques'],['hunter','Caçadora — eliminar suportes e objetivos']]){const o=el('option','',label);o.value=value;strategy.append(o);}const left=el('section','campaign-candidates')")
s=s.replace('heroIds:[...selected],requestId:', 'heroIds:[...selected],strategy:strategy.value,requestId:')
s=s.replace('slots,summary,el(\'small\'', 'strategy,slots,summary,el(\'small\'')
s=s.replace("body.append(left,right);", "const bestiary=el('div','campaign-bestiary');s.bestiary.names.forEach((name,i)=>{const card=el('div','');const image=el('img','');image.src=asset('enemy-'+s.id+'-'+i+'.png');image.alt=name;card.append(image,el('span','',name));bestiary.append(card);});left.append(bestiary,el('p','','Espadachim: golpes em grupo · Lanceiro: perfura defesa · Arqueiro: caça suportes · Maga: dano em área.'));right.append(el('p','','Destrua os objetivos para remover a proteção dos inimigos. Postura baixa causa uma breve interrupção, sem morte do herói.'));body.append(left,right);")
s=s.replace("renderer.init(host).then(()=>{if(dead)","renderer.init(host).then(async()=>{await mhInstallCampaignEnemyVisuals(renderer,stage,async monsterId=>{try{data=await request('campaign/target',{runId:data.run.id,monsterId});paint();}catch(e){error.textContent=e.message;}});if(dead)")
s=s.replace("mhCampaignDefense(sim,stage.bossDefense);", "mhInstallCampaignTactics(sim,{...stage,strategy:r.strategy},r.state);mhCampaignDefense(sim,stage.bossDefense);")
s=s.replace("'Os heróis percorrem o labirinto automaticamente. Inimigos mortos não renascem.'", "'Combate automático · Clique em um inimigo para priorizá-lo por 8s · Destrua os cristais de proteção.'")
p.write_text(s,encoding='utf-8')
p=Path('preparar-offline.cjs');s=p.read_text(encoding='utf-8-sig');s += "\nfor(const name of fs.readdirSync(path.join(__dirname,'assets/campaign-bestiary')).filter(n=>/^enemy-.*\\.png$/.test(n))){for(const dir of ['minihero-offline/build','shared-build'])fs.copyFileSync(path.join(__dirname,'assets/campaign-bestiary',name),path.join(__dirname,dir,name));}\n";p.write_text(s,encoding='utf-8')
